import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.performClick
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class DetailScreenRotationTest {
    @get:Rule
    val rule = createAndroidComposeRule<MainActivity>()

    @Test
    fun recreatingWhileDetailLoadsDoesNotCrashAndStillShowsProduct() {
        rule.waitUntil(10_000) {
            rule.onAllNodesWithTagCount("product_1") > 0
        }
        // product_1 has a deal (dealPercent > 0)
        rule.onNodeWithTag("product_1").performClick()

        rule.activityRule.scenario.recreate()

        rule.waitUntil(20_000) {
            rule.onAllNodesWithTagCount("detail_name") > 0
        }
        rule.onNodeWithTag("detail_name").assertExists()
